import com.comsol.model.*;import com.comsol.model.util.*;
/** Tabulated reference map avoids withsol limitations for stopped remesh output. */
public class TabulatedColumnALE {public static void main(String[] a){try{ModelUtil.initStandalone(false);Model m=ModelUtil.load("m",a[0]);
for(String n:new String[]{"volume","surface"}){String tag="ref"+n;m.func().create(tag,"Interpolation");m.func(tag).set("source","file");m.func(tag).set("filename",a[2]+"_"+n+"_unique.txt");m.func(tag).set("nargs",n.equals("volume")?2:1);m.func(tag).set("funcs",n.equals("volume")?new String[][]{{"refDR","1"},{"refDZ","2"}}:new String[][]{{"refEta","1"}});m.func(tag).set("interp","linear");m.func(tag).set("extrap","const");m.func(tag).importData();}
m.component("c").cpl().create("surfaceHeight","GeneralExtrusion");m.component("c").cpl("surfaceHeight").selection().geom("g",1);m.component("c").cpl("surfaceHeight").selection().named("surface");m.component("c").cpl("surfaceHeight").set("opname","surfaceHeight");m.component("c").cpl("surfaceHeight").set("srcframe","material");m.component("c").cpl("surfaceHeight").set("usesrcmap",true);m.component("c").cpl("surfaceHeight").set("srcmap",new String[]{"R","0"});m.component("c").cpl("surfaceHeight").set("dstmap",new String[]{"R","0"});
for(String f:m.component("c").common().tags())m.component("c").common().remove(f);
m.component("c").common().create("columnMesh","PrescribedDeformation");m.component("c").common("columnMesh").selection().all();m.component("c").common("columnMesh").set("prescribedDeformation",new String[]{"refDR(R/1[m],Z/1[m])*1[m]","0","refDZ(R/1[m],Z/1[m])*1[m]+(surfaceHeight(etaSurface)*1[um]-refEta(R/1[m])*1[m])*if(Z>=0,1-Z/Zdom,1+Z/Dcu)"});m.sol("sol1").feature("t1").feature("remesh").active(false);m.save(a[1]);System.out.println("TABULATED COLUMN MESH READY");System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}}
